import React,{useEffect,useMemo,useRef,useState}from"react";
import{createRoot}from"react-dom/client";
import*as echarts from"echarts/core";
import{BarChart,GaugeChart}from"echarts/charts";
import{GridComponent,TooltipComponent,LegendComponent,MarkLineComponent}from"echarts/components";
import{CanvasRenderer}from"echarts/renderers";
import"./style.css";
import"./v22.css";
import"./v23.css";

echarts.use([BarChart,GaugeChart,GridComponent,TooltipComponent,LegendComponent,MarkLineComponent,CanvasRenderer]);

const SESSION_KEY="adspilot_session_v2",icons={home:"▥",search:"⌕",audience:"◉",location:"◎",strategy:"✎",history:"↻",test:"◔",columns:"▤",save:"▣",quick:"▧",sun:"☀",moon:"☾",table:"▦",chart:"▥"};
const iso=d=>{const x=new Date(d),p=n=>String(n).padStart(2,"0");return`${x.getFullYear()}-${p(x.getMonth()+1)}-${p(x.getDate())}`},dateOf=v=>new Date(`${String(v).slice(0,10)}T12:00:00`);
const ranges={today:()=>[new Date(),new Date()],yesterday:()=>{let d=new Date();d.setDate(d.getDate()-1);return[d,d]},seven:()=>{let a=new Date(),b=new Date();a.setDate(a.getDate()-6);return[a,b]},fifteen:()=>{let a=new Date(),b=new Date();a.setDate(a.getDate()-14);return[a,b]},thirty:()=>{let a=new Date(),b=new Date();a.setDate(a.getDate()-29);return[a,b]},ninety:()=>{let a=new Date(),b=new Date();a.setDate(a.getDate()-89);return[a,b]},month:()=>[new Date(new Date().getFullYear(),new Date().getMonth(),1),new Date()],previous:()=>{let n=new Date();return[new Date(n.getFullYear(),n.getMonth()-1,1),new Date(n.getFullYear(),n.getMonth(),0)]}};
const period=(key="month")=>{const[a,b]=(ranges[key]||ranges.month)();return{from:iso(a),to:iso(b)}},br=v=>v?dateOf(v).toLocaleDateString("pt-BR"):"—",datetime=v=>v?new Date(v).toLocaleString("pt-BR"):"—",num=v=>Number(v||0);
const integer=v=>new Intl.NumberFormat("pt-BR",{maximumFractionDigits:2}).format(num(v)),pct=v=>`${new Intl.NumberFormat("pt-BR",{maximumFractionDigits:1}).format(num(v))}%`;
const getSession=()=>{try{return JSON.parse(localStorage.getItem(SESSION_KEY)||"null")}catch{return null}};let config;
async function publicConfig(){if(config)return config;const r=await fetch("/api/public-config");if(!r.ok)throw Error("Autenticação não configurada");return config=await r.json()}
async function refresh(s){const c=await publicConfig(),r=await fetch(`${c.supabaseUrl}/auth/v1/token?grant_type=refresh_token`,{method:"POST",headers:{apikey:c.supabaseAnonKey,"content-type":"application/json"},body:JSON.stringify({refresh_token:s.refresh_token})});if(!r.ok)throw Error("Sessão expirada");const n=await r.json();localStorage.setItem(SESSION_KEY,JSON.stringify(n));return n}
async function api(path,init={},retry=true){let s=getSession(),r=await fetch(path,{...init,headers:{"content-type":"application/json",authorization:`Bearer ${s?.access_token||""}`,...init.headers}});if(r.status===401&&retry&&s?.refresh_token){await refresh(s);return api(path,init,false)}const d=await r.json().catch(()=>({}));if(!r.ok)throw Error(d.error||"Operação não concluída");return d}

function Login({onLogin}){const[email,setEmail]=useState(""),[password,setPassword]=useState(""),[error,setError]=useState(""),[busy,setBusy]=useState(false);async function submit(e){e.preventDefault();setBusy(true);try{const c=await publicConfig(),r=await fetch(`${c.supabaseUrl}/auth/v1/token?grant_type=password`,{method:"POST",headers:{apikey:c.supabaseAnonKey,"content-type":"application/json"},body:JSON.stringify({email,password})}),s=await r.json();if(!r.ok)throw Error(s.error_description||"E-mail ou senha inválidos");localStorage.setItem(SESSION_KEY,JSON.stringify(s));onLogin(s)}catch(x){setError(x.message)}finally{setBusy(false)}}return <main className="login"><form className="loginCard" onSubmit={submit}><Brand big/><label className="kicker">ACESSO SEGURO</label><h1>Bem-vindo ao AdsPilot</h1><p>Entre para acompanhar suas campanhas e decisões.</p><label>E-mail<input type="email" value={email} onChange={e=>setEmail(e.target.value)} required/></label><label>Senha<input type="password" value={password} onChange={e=>setPassword(e.target.value)} required/></label>{error&&<div className="alert">{error}</div>}<button className="primary" disabled={busy}>{busy?"Entrando…":"Entrar no painel"}</button></form></main>}
function Brand({big=false}){return <div className={`brand ${big?"big":""}`}><b>A</b><div><strong>AdsPilot</strong><small>Google Ads Intelligence · V2.3</small></div></div>}

function RangePicker({dates,setDates,close}){const[view,setView]=useState(dateOf(dates.from)),[draft,setDraft]=useState(dates),[selecting,setSelecting]=useState("from");const first=new Date(view.getFullYear(),view.getMonth(),1),offset=(first.getDay()+6)%7,days=new Date(view.getFullYear(),view.getMonth()+1,0).getDate(),cells=Array(offset).fill(null).concat(Array.from({length:days},(_,i)=>new Date(view.getFullYear(),view.getMonth(),i+1)));function choose(d){const value=iso(d);if(d>new Date())return;if(selecting==="from"||value<draft.from){setDraft({from:value,to:value});setSelecting("to")}else{setDraft({...draft,to:value});setSelecting("from")}}return <div className="rangePopover"><div className="rangeHead"><button onClick={()=>setView(new Date(view.getFullYear(),view.getMonth()-1,1))}>‹</button><strong>{view.toLocaleDateString("pt-BR",{month:"long",year:"numeric"})}</strong><button onClick={()=>setView(new Date(view.getFullYear(),view.getMonth()+1,1))}>›</button></div><div className="week">{["S","T","Q","Q","S","S","D"].map((x,i)=><span key={i}>{x}</span>)}</div><div className="calendarGrid">{cells.map((d,i)=>d?<button key={i} disabled={d>new Date()} className={`${iso(d)>=draft.from&&iso(d)<=draft.to?"inRange":""} ${iso(d)===draft.from||iso(d)===draft.to?"edge":""}`} onClick={()=>choose(d)}>{d.getDate()}</button>:<span key={i}/>)}</div><div className="rangeDates"><span>Início <b>{br(draft.from)}</b></span><span>Fim <b>{br(draft.to)}</b></span></div><div className="rangeActions"><button onClick={()=>setDraft({from:iso(new Date()),to:iso(new Date())})}>Limpar</button><button onClick={close}>Cancelar</button><button className="primary" onClick={()=>{setDates(draft);close()}}>Aplicar</button></div></div>}
function Header({session,back,logout,theme,setTheme,currency,setCurrency,dates,setDates,periodKey,setPeriodKey,scope}){const[showRange,setShowRange]=useState(false);async function preset(v){setPeriodKey(v);if(v==="custom")return setShowRange(true);if(v==="all"){try{const q=scope?`?customer_id=${scope.customer_id}&campaign_id=${scope.campaign_id}`:"";const b=await api(`/api/v2/data-bounds${q}`);setDates({from:b.first_date||iso(new Date()),to:b.last_date||iso(new Date())})}catch{setDates(period("ninety"))}return}setDates(period(v))}return <header><div className="headerLeft">{back&&<button className="iconBtn" onClick={back}>←</button>}<Brand/></div><div className="toolbar"><div className="rangeWrap"><select value={periodKey} onChange={e=>preset(e.target.value)}><option value="today">Hoje</option><option value="yesterday">Ontem</option><option value="seven">7 dias</option><option value="fifteen">15 dias</option><option value="thirty">30 dias</option><option value="ninety">90 dias</option><option value="month">Este mês</option><option value="previous">Mês passado</option><option value="all">Todo o período</option><option value="custom">Personalizado</option></select><button className="dateButton" onClick={()=>{setPeriodKey("custom");setShowRange(!showRange)}}>{br(dates.from)} → {br(dates.to)}</button>{showRange&&<RangePicker dates={dates} setDates={setDates} close={()=>setShowRange(false)}/>}</div><div className="currency">{["USD","BRL","EUR"].map(x=><button className={currency===x?"active":""} onClick={()=>setCurrency(x)} key={x}>{x}</button>)}</div><button className="iconBtn" onClick={()=>setTheme(theme==="dark"?"light":"dark")}>{theme==="dark"?icons.sun:icons.moon}</button><button className="avatar" title={session?.user?.email} onClick={logout}>Sair</button></div></header>}

function useSort(rows,initial=""){const[sort,setSort]=useState({key:initial,dir:"desc"});const output=useMemo(()=>[...rows].sort((a,b)=>{let x=a[sort.key],y=b[sort.key];if(x==null)return 1;if(y==null)return-1;return(typeof x==="number"?x-y:String(x).localeCompare(String(y)))*(sort.dir==="asc"?1:-1)}),[rows,sort]);return[output,key=>setSort(s=>({key,dir:s.key===key&&s.dir==="desc"?"asc":"desc"})),sort]}
function SortTh({id,sort,onSort,children}){return <th onClick={()=>onSort(id)}>{children}<i>{sort.key===id?(sort.dir==="asc"?" ↑":" ↓"):""}</i></th>}
const totals=rows=>rows.reduce((a,r)=>({cost:a.cost+num(r.cost??num(r.cost_micros)/1e6),revenue:a.revenue+num(r.revenue??r.conversion_value),conversions:a.conversions+num(r.conversions),clicks:a.clicks+num(r.clicks),impressions:a.impressions+num(r.impressions)}),{cost:0,revenue:0,conversions:0,clicks:0,impressions:0});
function EChart({option,height=300,className=""}){const ref=useRef(null),chart=useRef(null);useEffect(()=>{if(!ref.current)return;chart.current?.dispose();chart.current=echarts.init(ref.current,null,{renderer:"canvas"});chart.current.setOption(option,true);const resize=()=>chart.current?.resize(),observer=new ResizeObserver(resize);observer.observe(ref.current);window.addEventListener("resize",resize);return()=>{observer.disconnect();window.removeEventListener("resize",resize);chart.current?.dispose()}},[option]);return <div ref={ref} className={`echart ${className}`} style={{height}}/>}
const chartTheme=()=>{const dark=document.documentElement.dataset.theme!=="light";return{dark,text:dark?"#94a3b8":"#475569",grid:dark?"#233044":"#dce5f0",tip:dark?"#0b1220":"#fff",border:dark?"#334155":"#cbd5e1"}}
async function exportWorkbook(name,sheets){const{default:ExcelJS}=await import("exceljs"),wb=new ExcelJS.Workbook();wb.creator="AdsPilot Analytics";for(const sheet of sheets){const ws=wb.addWorksheet(sheet.name.slice(0,31));ws.columns=sheet.columns.map(c=>({header:c.label,key:c.id,width:Math.max(12,Math.min(34,c.label.length+5))}));ws.addRows(sheet.rows);ws.views=[{state:"frozen",ySplit:1}];ws.autoFilter={from:{row:1,column:1},to:{row:1,column:sheet.columns.length}};ws.getRow(1).font={bold:true,color:{argb:"FFFFFFFF"}};ws.getRow(1).fill={type:"pattern",pattern:"solid",fgColor:{argb:"FF182235"}};ws.eachRow((row,i)=>{if(i%2===0)row.fill={type:"pattern",pattern:"solid",fgColor:{argb:"FFF1F5F9"}}})}const out=await wb.xlsx.writeBuffer(),url=URL.createObjectURL(new Blob([out],{type:"application/vnd.openxmlformats-officedocument.spreadsheetml.sheet"})),a=document.createElement("a");a.href=url;a.download=`${name}.xlsx`;a.click();URL.revokeObjectURL(url)}
function MetricCards({m,money}){const profit=m.revenue-m.cost,cards=[["Receita total",money(m.revenue),"blue"],["Custo Ads",money(m.cost),"orange"],["Lucro líquido",money(profit),profit>=0?"green":"red"],["ROI",pct(m.cost?profit/m.cost*100:0),"purple"],["CPA",m.conversions?money(m.cost/m.conversions):"—","cyan"]];return <section className="metricCards">{cards.map(([l,v,c])=><article className={c} key={l}><small>{l}</small><strong>{v}</strong></article>)}</section>}
function DailyChart({rows,money}){const data=[...rows].sort((a,b)=>String(a.report_date).localeCompare(String(b.report_date))).map(r=>({date:r.report_date,revenue:num(r.revenue??r.conversion_value),cost:num(r.cost??num(r.cost_micros)/1e6)})),t=chartTheme(),option=useMemo(()=>({animation:true,animationDuration:650,color:["#3b82f6","#f97316","#10b981"],grid:{left:54,right:24,top:35,bottom:42,containLabel:true},legend:{top:0,right:18,textStyle:{color:t.text}},tooltip:{trigger:"axis",appendToBody:true,confine:false,backgroundColor:t.tip,borderColor:t.border,textStyle:{color:t.text},formatter:p=>{const i=p[0]?.dataIndex||0,x=data[i],profit=x.revenue-x.cost;return `<b>${br(x.date)}</b><br/>📈 Receita: ${money(x.revenue)}<br/>🛠 Custo: ${money(x.cost)}<br/>💰 Lucro: ${money(profit)}`}},xAxis:{type:"category",data:data.map(x=>String(x.date).slice(5)),axisLabel:{color:t.text},axisLine:{lineStyle:{color:t.grid}}},yAxis:{type:"value",axisLabel:{color:t.text},splitLine:{lineStyle:{color:t.grid,type:"dashed"}}},series:[{name:"Receita",type:"bar",barMaxWidth:28,data:data.map(x=>x.revenue),itemStyle:{borderRadius:[5,5,0,0]}},{name:"Custo",type:"bar",barMaxWidth:28,data:data.map(x=>x.cost),itemStyle:{borderRadius:[5,5,0,0]}},{name:"Lucro",type:"bar",barMaxWidth:28,data:data.map(x=>x.revenue-x.cost),itemStyle:{borderRadius:[5,5,0,0],color:p=>p.value<0?"#f43f5e":"#10b981"}}]}),[rows,money,t.dark]);return <section className="panel chart"><div className="panelTitle"><h2>Evolução diária</h2></div>{data.length?<EChart option={option} height={270}/>:<Empty text="Sem dados no período"/>}</section>}
function Empty({text="Nenhum dado encontrado"}){return <div className="empty">◇<span>{text}</span></div>}
function ColumnModal({columns,visible,setVisible,close}){return <div className="overlay"><section className="modal columns"><div className="modalHead"><div><b>{icons.columns}</b><h2>Personalizar colunas</h2></div><button onClick={close}>×</button></div><div className="columnList">{columns.map(c=><label key={c.id}><input type="checkbox" checked={visible.includes(c.id)} onChange={()=>setVisible(visible.includes(c.id)?visible.filter(x=>x!==c.id):[...visible,c.id])}/><span>{c.label}</span></label>)}</div><button className="primary" onClick={close}>Confirmar</button></section></div>}
const conditional=(v,avg)=>v<0?"bad":v===0?"neutral":v<avg?"warn":"good";

const campaignCols=[{id:"campaign_name",label:"Campanha",group:"fixed"},{id:"revenue",label:"Receita",group:"primary"},{id:"cost",label:"Custo",group:"primary"},{id:"profit",label:"Lucro",group:"primary"},{id:"roi",label:"ROI",group:"primary"},{id:"margin",label:"Margem",group:"primary"},{id:"cpa",label:"Custo/Conversão",group:"primary"},{id:"desired_cpa",label:"CPA médio desejado",group:"primary"},{id:"impressions",label:"Impressões",group:"secondary"},{id:"clicks",label:"Cliques",group:"secondary"},{id:"ctr",label:"CTR",group:"secondary"},{id:"cpc",label:"CPC médio",group:"secondary"},{id:"conversions",label:"Conversões",group:"secondary"},{id:"conversion_rate",label:"Taxa de conversão",group:"secondary"},{id:"last_execution_date",label:"Última execução",group:"secondary"},{id:"campaign_start_date",label:"Data de criação",group:"secondary"},{id:"status",label:"Status",group:"secondary"},{id:"final_url",label:"URL final",group:"secondary"},{id:"ad_group_count",label:"Grupos AD",group:"secondary"},{id:"ad_count",label:"Anúncios AD",group:"secondary"}];
function GroupHead({cols,visible}){const f=cols.filter(x=>visible.includes(x.id)),count=g=>f.filter(x=>x.group===g).length;return <><tr className="superHead">{!!count("fixed")&&<th colSpan={count("fixed")} className="fixedGroup">Identificação</th>}{!!count("primary")&&<th colSpan={count("primary")} className="primaryGroup">Métricas primárias</th>}{!!count("secondary")&&<th colSpan={count("secondary")} className="secondaryGroup">Métricas secundárias</th>}</tr></>}
function CampaignGrid({rows,money,open}){const storage="adspilot_columns_campaign_v23",[visible,setVisibleState]=useState(()=>{try{return JSON.parse(localStorage.getItem(storage))||campaignCols.map(x=>x.id)}catch{return campaignCols.map(x=>x.id)}}),setVisible=v=>{setVisibleState(v);localStorage.setItem(storage,JSON.stringify(v))},[show,setShow]=useState(false),[sorted,sort,sorting]=useSort(rows,"cost"),t=totals(rows),avg={profit:rows.length?(t.revenue-t.cost)/rows.length:0,roi:t.cost?(t.revenue-t.cost)/t.cost*100:0,margin:t.revenue?(t.revenue-t.cost)/t.revenue*100:0};const final={...t,profit:t.revenue-t.cost,roi:avg.roi,margin:avg.margin,ctr:t.impressions?t.clicks/t.impressions:0,cpc:t.clicks?t.cost/t.clicks:0,conversion_rate:t.clicks?t.conversions/t.clicks*100:0,cpa:t.conversions?t.cost/t.conversions:null,desired_cpa:rows.filter(x=>num(x.desired_cpa)).length?rows.reduce((a,x)=>a+num(x.desired_cpa),0)/rows.filter(x=>num(x.desired_cpa)).length:null};function render(c,id,total=false){const values={campaign_name:total?<strong>Σ TOTAL / Ø MÉDIA</strong>:<><strong>{c.campaign_name}</strong><small>{c.account_name} · #{c.campaign_id}</small></>,revenue:<b className="revenueText">{money(c.revenue)}</b>,cost:<b className="costText">{money(c.cost)}</b>,profit:<b className={total?"good":conditional(c.profit,avg.profit)}>{money(c.profit)}</b>,roi:<b className={total?"good":conditional(c.roi,avg.roi)}>{pct(c.roi)}</b>,margin:<b className={total?"good":conditional(c.margin,avg.margin)}>{pct(c.margin)}</b>,cpa:c.cpa==null?"—":money(c.cpa),desired_cpa:c.desired_cpa?`${money(c.desired_cpa)}${c.desired_cpa_is_average?" (Média)":""}`:"—",impressions:integer(c.impressions),clicks:integer(c.clicks),ctr:pct(num(c.ctr)*100),cpc:money(c.cpc),conversions:integer(c.conversions),conversion_rate:pct(c.conversion_rate),last_execution_date:br(c.last_execution_date),campaign_start_date:br(c.campaign_start_date),status:<span className={`status ${c.status==="ENABLED"?"on":""}`}>{c.status||"—"}</span>,final_url:c.final_url?<button className="url" onClick={e=>{e.stopPropagation();window.open(c.final_url,"_blank","noopener,noreferrer")}}>Abrir ↗</button>:"—",ad_group_count:integer(c.ad_group_count),ad_count:integer(c.ad_count)};return values[id]}const active=campaignCols.filter(c=>visible.includes(c.id));async function excel(){const monetary=new Set(["revenue","cost","profit","cpc","cpa","desired_cpa"]),percent=new Set(["roi","margin","conversion_rate"]),raw=[{campaign_name:"Σ TOTAL / Ø MÉDIA",...final},...sorted].map(c=>Object.fromEntries(active.map(x=>{let v=c[x.id]??(x.id==="profit"?num(c.revenue)-num(c.cost):null);if(monetary.has(x.id)&&v!=null)v=money(v);if(percent.has(x.id)&&v!=null)v=pct(v);if(x.id==="ctr")v=pct(num(v)*100);return[x.id,v]})));await exportWorkbook("adspilot-campanhas",[{name:"Campanhas",columns:active,rows:raw}])}return <section className="panel"><div className="panelTitle"><div><h2>Campanhas</h2><p>{rows.length} campanhas encontradas</p></div><div className="panelActions"><button onClick={excel}>⇩ Exportar XLSX</button><button onClick={()=>setShow(true)}>{icons.columns} Personalizar colunas</button></div></div><div className="table"><table className="groupedTable"><thead><GroupHead cols={campaignCols} visible={visible}/><tr>{active.map(c=><SortTh key={c.id} id={c.id} onSort={sort} sort={sorting}>{c.label}</SortTh>)}</tr></thead><tbody><tr className="totalRow">{active.map(c=><td key={c.id}>{render(final,c.id,true)}</td>)}</tr>{sorted.map(c=><tr key={`${c.customer_id}:${c.campaign_id}`} onClick={()=>open(c)}>{active.map(x=><td key={x.id}>{render(c,x.id)}</td>)}</tr>)}</tbody></table></div>{show&&<ColumnModal columns={campaignCols} visible={visible} setVisible={setVisible} close={()=>setShow(false)}/>}</section>}
function Dashboard({common,open}){const[data,setData]=useState(null),[query,setQuery]=useState(""),[account,setAccount]=useState(""),[status,setStatus]=useState(""),[error,setError]=useState("");async function load(){try{setData(await api(`/api/v2/dashboard?${new URLSearchParams({...common.dates,currency:""})}`))}catch(e){setError(e.message)}}useEffect(()=>{load()},[common.dates.from,common.dates.to]);const rows=useMemo(()=>(data?.campaigns||[]).filter(c=>(!account||c.account_name===account)&&(!status||c.status===status)&&c.campaign_name.toLowerCase().includes(query.toLowerCase())),[data,query,account,status]),m=totals(rows);return <main><Header {...common}/><section className="pageIntro"><div><label className="kicker">VISÃO CONSOLIDADA</label><h1>Performance das campanhas</h1><p>Rentabilidade, mudanças e oportunidades em um único painel.</p></div><span className="sync">● Sincronizado {datetime(data?.last_sync?.finished_at)}</span></section><div className="filters"><select value={account} onChange={e=>setAccount(e.target.value)}><option value="">Todas as contas</option>{(data?.accounts||[]).map(x=><option key={x}>{x}</option>)}</select><select value={status} onChange={e=>setStatus(e.target.value)}><option value="">Todos os status</option>{[...new Set((data?.campaigns||[]).map(x=>x.status))].map(x=><option key={x}>{x}</option>)}</select><input placeholder="⌕ Buscar campanha…" value={query} onChange={e=>setQuery(e.target.value)}/><button onClick={load}>↻ Atualizar</button></div>{error&&<div className="alert">{error}</div>}<MetricCards m={m} money={common.money}/><DailyChart rows={data?.daily||[]} money={common.money}/><CampaignGrid rows={rows} money={common.money} open={c=>open({...c,period:common.dates})}/></main>}

const detailCols=[{id:"report_date",label:"Data",group:"fixed"},{id:"notes",label:"Anotações / Histórico",group:"fixed"},{id:"account",label:"Conta",group:"fixed"},{id:"conversion_value",label:"Receita",group:"primary"},{id:"cost_micros",label:"Custo",group:"primary"},{id:"profit",label:"Lucro",group:"primary"},{id:"cpa",label:"Custo/Conversão",group:"primary"},{id:"desired_cpa",label:"CPA desejado",group:"primary"},{id:"roi",label:"ROI",group:"primary"},{id:"margin",label:"Margem",group:"primary"},{id:"impressions",label:"Impressões",group:"secondary"},{id:"clicks",label:"Cliques",group:"secondary"},{id:"ctr",label:"CTR",group:"secondary"},{id:"average_cpc_micros",label:"CPC médio",group:"secondary"},{id:"conversions",label:"Conversões",group:"secondary"},{id:"conversion_rate",label:"Taxa de conversão",group:"secondary"},{id:"budget_micros",label:"Orçamento diário",group:"secondary"},{id:"bidding_strategy_type",label:"Estratégia",group:"secondary"},{id:"search_top_impression_share",label:"% impr. (parte sup.)",group:"secondary"},{id:"search_absolute_top_impression_share",label:"% impr. (1ª posição)",group:"secondary"},{id:"search_impression_share",label:"Parcela impr. pesquisa",group:"secondary"},{id:"page_visits",label:"Visitas pág.",group:"secondary"},{id:"vsl_clicks",label:"Cliques VSL",group:"secondary"},{id:"vsl_checkouts",label:"Checkout VSL",group:"secondary"},{id:"general_checkouts",label:"Checkout geral",group:"secondary"},{id:"page_leak",label:"Fuga página",group:"secondary"},{id:"bridge_leak",label:"Fuga bridge",group:"secondary"},{id:"vsl_leak",label:"Fuga VSL",group:"secondary"},{id:"final_url",label:"Página anúncio",group:"secondary"}];
