function BreakdownPanel({title,rows,money,label,onClick,topControls=false}){const[view,setView]=useState("table"),[top,setTop]=useState(10),[rank,setRank]=useState("cost_micros");let shown=[...rows].sort((a,b)=>num(b[rank])-num(a[rank]));if(view==="chart"&&topControls&&shown.length>top){const rest=shown.slice(top);shown=shown.slice(0,top);shown.push({...aggregate(rest,()=>"Outros")[0],label:"Outros"})}return <article className="panel breakdown"><div className="panelTitle"><h2>{title}</h2><div className="viewTools">{view==="chart"&&topControls&&<><select value={rank} onChange={e=>setRank(e.target.value)}><option value="cost_micros">Top por custo</option><option value="clicks">Top por cliques</option><option value="conversion_value">Top por receita</option></select>{[3,5,10].map(n=><button className={top===n?"active":""} onClick={()=>setTop(n)} key={n}>Top {n}</button>)}<input type="number" min="1" max="100" value={top} onChange={e=>setTop(Math.max(1,Math.min(100,num(e.target.value))))}/></>}<button className={view==="table"?"active":""} onClick={()=>setView("table")}>{icons.table} Tabela</button><button className={view==="chart"?"active":""} onClick={()=>setView("chart")}>{icons.chart} Gráfico</button></div></div>{view==="table"?<AggregateTable rows={rows} money={money} label={label} onClick={onClick}/>:<PercentChart rows={shown} money={money}/>}</article>}
