function Locations({rows,money}){const[level,setLevel]=useState("country"),[country,setCountry]=useState(null),[state,setState]=useState(null);function key(r){return level==="country"?r.country_name:level==="state"?`${r.state_name}|||${r.country_name}`:`${r.city_name}|||${r.state_name}|||${r.country_name}`}let filtered=rows.filter(r=>r.location_level===level&&(!country||r.country_id===country.country_id)&&(!state||r.state_id===state.state_id)),data=aggregate(filtered,key).map(r=>{const p=r.label.split("|||");return level==="country"?{...r,label:p[0]}:level==="state"?{...r,label:p[0],country_name:p[1]}:{...r,label:p[0],state_name:p[1],country_name:p[2]}});function change(v){setLevel(v);setCountry(null);setState(null)}function drill(r){if(level==="country"){const raw=filtered.find(x=>x.country_name===r.label);setCountry(raw);setLevel("state")}else if(level==="state"){const raw=filtered.find(x=>x.state_name===r.label);setState(raw);setLevel("city")}}return <section><div className="locationNav"><div className="breadcrumbs"><button onClick={()=>change("country")}>Todos os países</button>{country&&<><span>›</span><button onClick={()=>{setLevel("state");setState(null)}}>{country.country_name}</button></>}{state&&<><span>›</span><b>{state.state_name}</b></>}</div><div className="segmented">{[["country","País"],["state","Estado"],["city","Cidade"]].map(([v,l])=><button className={level===v?"active":""} onClick={()=>change(v)} key={v}>{l}</button>)}</div></div><BreakdownPanel title={`${icons.location} Performance por local`} rows={data} money={money} label={level==="country"?"País":level==="state"?"Estado":"Cidade"} onClick={level!=="city"?drill:null} topControls/></section>}

function CycleControl({data,money,onConfigure}){const s=data?.setting||{},m=data?.test_metrics||{},commission=num(s.commission_value),cost=num(m.cost),sales=num(m.conversions),desired=num(m.desired_cpa)||num(data?.daily?.[0]?.desired_cpa_micros)/1e6,target=num(s.test_limit_percent||80),cycle=Math.floor(cost/(desired||1))+1,cpaProgress=desired?(cost%desired)/desired*100:0,cpaRemaining=desired?desired-(cost%desired):0,netCost=cost-sales*commission,consumption=commission?Math.max(0,netCost/commission*100):0,commissionMultiple=commission?cost/commission:0,commissionCycle=Math.floor(sales)+1,showCommission=s.commission_visibility!=="no_sales"||sales===0,showCpa=s.show_cpa_cycle!==false,t=chartTheme();const progressOption=useMemo(()=>({animationDuration:800,grid:{left:0,right:0,top:12,bottom:12},xAxis:{type:"value",min:0,max:Math.max(100,consumption*1.08),show:false},yAxis:{type:"category",data:[""],show:false},series:[{type:"bar",data:[consumption],barWidth:20,itemStyle:{borderRadius:10,color:new echarts.graphic.LinearGradient(0,0,1,0,[{offset:0,color:"#13d8a0"},{offset:.55,color:"#facc15"},{offset:1,color:"#ff4f78"}])},markLine:{symbol:"none",silent:true,label:{show:true,formatter:`Meta ${target}%`,color:t.text,position:"insideEndTop"},lineStyle:{color:"#fff",width:2},data:[{xAxis:target}]}}]}),[consumption,target,t.dark]),gaugeOption=useMemo(()=>({animationDuration:900,series:[{type:"gauge",startAngle:210,endAngle:-30,min:0,max:100,center:["50%","58%"],radius:"92%",progress:{show:true,width:14,roundCap:true,itemStyle:{color:new echarts.graphic.LinearGradient(0,0,1,0,[{offset:0,color:"#7157ff"},{offset:1,color:"#15d8e8"}])}},axisLine:{lineStyle:{width:14,color:[[1,"#263447"]]}},pointer:{show:false},axisTick:{show:false},splitLine:{show:false},axisLabel:{show:false},detail:{valueAnimation:true,formatter:`${cpaProgress.toFixed(1).replace(".",",")}%\n{cycle|${cycle}º ciclo}`,offsetCenter:[0,"8%"],color:"#50dbea",fontSize:24,fontWeight:800,rich:{cycle:{color:t.text,fontSize:13,lineHeight:26}}},data:[{value:cpaProgress}]}]}),[cpaProgress,cycle,t.dark]);if(!showCommission&&!showCpa)return null;return <section className="cycleControl panel"><div className="controlTitle"><b>◇ CONTROLE DE PERFORMANCE</b><small>Escopo: {s.cycle_scope==="conversion_window"?`últimos ${s.conversion_window_days||7} dias`:"todo o período configurado"}</small></div><div className="cycleGrid">{showCommission&&<article className="commissionCycle"><div className="cycleHeading"><div><small>CONSUMO LÍQUIDO DA COMISSÃO</small><strong className={!commission?"muted":consumption>target?"bad":consumption>0?"warn":"good"}>{commission?pct(consumption):"Configuração necessária"}</strong></div>{commission&&<div className="cyclePills"><span className="pill cycleNumber">{commissionCycle}º ciclo</span><span className={consumption>target?"pill danger":"pill"}>{consumption>target?`+${pct(consumption-target)} acima da meta`:`${pct(target-consumption)} disponíveis`}</span></div>}</div>{commission?<><EChart option={progressOption} height={72}/><div className="cycleStats"><span>Comissão por venda<b>{money(commission)}</b></span><span>Custo acumulado<b>{money(cost)}</b></span><span>Vendas acumuladas<b>{integer(sales)}</b></span><span>Custo em comissões<b>{commissionMultiple.toFixed(2).replace(".",",")}×</b></span></div><div className="cycleFooter"><span>Consumido no ciclo <b>{money(Math.max(0,netCost))}</b></span><span>{netCost<0?<>Saldo protegido <b className="good">{money(Math.abs(netCost))}</b></>:consumption>target?<>Excedente da meta <b className="bad">{money(netCost-commission*target/100)}</b></>:<>Falta até a meta <b>{money(commission*target/100-netCost)}</b></>}</span></div></>:<div className="cycleWarning"><b>Defina a comissão por venda</b><p>O Ciclo da Comissão será calculado depois que esse valor for salvo na aba Configurações.</p><button onClick={onConfigure}>Abrir Configurações</button></div>}</article>}{showCpa&&<article className="cpaCycle"><div><small>CICLO DO CPA</small>{desired?<EChart option={gaugeOption} height={190}/>:<div className="cycleWarning"><b>CPA desejado não encontrado</b><p>Configure um CPA na campanha ou nos grupos de anúncios do Google Ads.</p></div>}</div>{desired&&<div className="cpaFacts"><span>CPA médio desejado<b>{money(desired)}</b></span><span>Falta para completar o ciclo<b>{money(cpaRemaining)}</b></span><small>{integer(sales)} venda(s) registrada(s) · indicador de consumo, não previsão de venda</small></div>}</article>}</div></section>}

function Detail({campaign,common,back}){const[tab,setTab]=useState("overview"),[data,setData]=useState(null),[quick,setQuick]=useState(false),[error,setError]=useState(""),[strategy,setStrategy]=useState(""),[note,setNote]=useState("");async function load(){try{const d=await api(`/api/v2/campaign?${new URLSearchParams({customer_id:campaign.customer_id,campaign_id:campaign.campaign_id,...common.dates})}`);setData(d);setStrategy(d.strategy?.content||"")}catch(e){setError(e.message)}}useEffect(()=>{load()},[common.dates.from,common.dates.to]);const tabs=[["overview",icons.home,"Visão geral"],["terms",icons.search,"Termos de pesquisa"],["audience",icons.audience,"Públicos"],["location",icons.location,"Locais"],["strategy",icons.strategy,"Estratégia"],["history",icons.history,"Alterações e notas"],["test",icons.test,"Configurações"]],m=totals(data?.daily||[]);async function saveStrategy(){await api("/api/v2/strategy",{method:"PUT",body:JSON.stringify({customer_id:campaign.customer_id,campaign_id:campaign.campaign_id,content:strategy})});load()}async function addNote(){if(!note.trim())return;await api("/api/v2/notes",{method:"POST",body:JSON.stringify({customer_id:campaign.customer_id,campaign_id:campaign.campaign_id,content:note})});setNote("");load()}return <main><Header {...common} back={back} scope={campaign}/><section className="campaignTitle"><div><h1>{campaign.campaign_name}</h1><p>{campaign.account_name} · #{campaign.campaign_id} · {campaign.channel_type}</p></div><div>{data?.setting?.commission_value&&<span className="commissionBadge">Comissão {common.money(data.setting.commission_value)}</span>}<span className="status on">{campaign.status}</span><button className="primary quickBtn" onClick={()=>setQuick(true)}>{icons.quick} Lançamento rápido</button></div></section><nav className="tabs">{tabs.map(([id,ic,l])=><button key={id} className={tab===id?`active ${id}`:""} onClick={()=>setTab(id)}><b>{ic}</b>{l}</button>)}</nav>{error&&<div className="alert">{error}</div>}{tab==="overview"&&<><CycleControl data={data} money={common.money} onConfigure={()=>setTab("test")}/><h3 className="sectionLabel">Métricas do período selecionado</h3><MetricCards m={m} money={common.money}/><DailyChart rows={data?.daily||[]} money={common.money}/><DetailGrid data={data||{}} money={common.money} campaign={campaign} reload={load}/></>}{tab==="terms"&&<BreakdownPanel title="Termos de pesquisa" rows={aggregate(data?.search_terms||[],x=>x.search_term)} money={common.money} label="Termo"/>}{tab==="audience"&&<Audience segments={data?.segments||[]} money={common.money}/>} {tab==="location"&&<Locations rows={data?.locations||[]} money={common.money}/>} {tab==="strategy"&&<section className="panel strategy"><div className="panelTitle"><div><h2>{icons.strategy} Estratégia da campanha</h2><p>Registre tese, ângulos, limites de CPA e regras de escala.</p></div></div><textarea value={strategy} onChange={e=>setStrategy(e.target.value)}/><div><small>Última atualização: {datetime(data?.strategy?.updated_at)}</small><button className="primary" onClick={saveStrategy}>{icons.save} Salvar estratégia</button></div></section>}{tab==="history"&&<section className="notes"><article className="panel noteComposer"><h2>✎ Adicionar nota</h2><textarea value={note} onChange={e=>setNote(e.target.value)}/><button className="primary" onClick={addNote}>Salvar nota</button></article><article className="panel timeline"><div className="panelTitle"><h2>Linha do tempo</h2></div>{[...(data?.changes||[]).map(x=>({date:x.change_date_time,title:x.change_resource_type,text:x.summary,kind:"auto"})),...(data?.notes||[]).map(x=>({date:x.created_at,title:x.title||"Nota manual",text:x.content,kind:"manual"}))].sort((a,b)=>new Date(b.date)-new Date(a.date)).map((x,i)=><div className={`event ${x.kind}`} key={i}><b>{x.kind==="auto"?icons.history:icons.strategy}</b><div><strong>{x.title}</strong><small>{datetime(x.date)}</small><p>{x.text}</p></div></div>)}</article></section>}{tab==="test"&&<TestSettings data={data} campaign={campaign} currency={common.currency} reload={load}/>} {quick&&<QuickModal campaign={campaign} currency={common.currency} close={()=>setQuick(false)} saved={()=>{setQuick(false);load()}}/>}</main>}
function TestSettings({data,campaign,currency,reload}){const defaults={campaign_type:"main",commission_value:"",test_limit_percent:80,test_start_date:iso(new Date()),commission_visibility:"always",show_cpa_cycle:true,cycle_scope:"all",conversion_window_days:7,active:true},[f,setF]=useState({...defaults,...data?.setting});useEffect(()=>{if(data?.setting)setF({...defaults,...data.setting})},[data]);async function save(e){e.preventDefault();await api("/api/v2/campaign-settings",{method:"PUT",body:JSON.stringify({...f,customer_id:campaign.customer_id,campaign_id:campaign.campaign_id,currency_code:currency})});reload()}return <section className="settingsGrid"><form className="panel settings settingsWide" onSubmit={save}><div><h2>◔ Configurações da campanha</h2><p>Defina os parâmetros usados nos indicadores. Isso não altera sua campanha no Google Ads.</p></div><div className="formGrid two"><label>Tipo<select value={f.campaign_type} onChange={e=>setF({...f,campaign_type:e.target.value})}><option value="main">Principal</option><option value="test">Teste</option></select></label><label>Comissão por venda<input type="number" min="0" step="0.01" value={f.commission_value??""} onChange={e=>setF({...f,commission_value:e.target.value})}/></label><label>Meta máxima de consumo (%)<input type="number" min="1" max="500" value={f.test_limit_percent} onChange={e=>setF({...f,test_limit_percent:e.target.value})}/></label><label>Início do acompanhamento<input type="date" value={f.test_start_date||""} onChange={e=>setF({...f,test_start_date:e.target.value})}/></label><label>Exibir Ciclo da Comissão<select value={f.commission_visibility} onChange={e=>setF({...f,commission_visibility:e.target.value})}><option value="always">Mostrar sempre</option><option value="no_sales">Apenas quando não existir venda</option></select></label><label>Escopo dos ciclos<select value={f.cycle_scope} onChange={e=>setF({...f,cycle_scope:e.target.value})}><option value="all">Todo o período desde o início</option><option value="conversion_window">Janela de conversão</option></select></label>{f.cycle_scope==="conversion_window"&&<label>Dias da janela de conversão<input type="number" min="1" max="90" value={f.conversion_window_days} onChange={e=>setF({...f,conversion_window_days:e.target.value})}/></label>}<label className="checkLabel"><input type="checkbox" checked={f.show_cpa_cycle!==false} onChange={e=>setF({...f,show_cpa_cycle:e.target.checked})}/> Mostrar sempre o Ciclo do CPA</label></div><button className="primary">Salvar configurações</button></form><article className="panel settingsHelp"><h2>Como os ciclos funcionam</h2><p><b>Consumo líquido da comissão:</b> custo acumulado menos as comissões das vendas já realizadas, comparado à próxima comissão.</p><p><b>Ciclo do CPA:</b> posição do custo dentro de blocos do CPA médio desejado. É um controle de gasto e não uma previsão de venda.</p><p><b>Moeda:</b> os valores continuam gravados na moeda original; a conversão ocorre somente na interface.</p></article></section>}
function App(){const[session,setSession]=useState(getSession()),[campaign,setCampaign]=useState(null),[theme,setTheme]=useState(localStorage.getItem("adspilot_theme")||"dark"),[currency,setCurrency]=useState(localStorage.getItem("adspilot_currency")||"USD"),[dates,setDates]=useState(period("month")),[periodKey,setPeriodKey]=useState("month"),[rates,setRates]=useState({USD:1,BRL:1,EUR:1});useEffect(()=>{document.documentElement.dataset.theme=theme;localStorage.setItem("adspilot_theme",theme)},[theme]);useEffect(()=>localStorage.setItem("adspilot_currency",currency),[currency]);useEffect(()=>{fetch("https://economia.awesomeapi.com.br/json/last/USD-BRL,USD-EUR").then(r=>r.json()).then(x=>setRates({USD:1,BRL:num(x.USDBRL?.bid)||1,EUR:num(x.USDEUR?.bid)||1})).catch(()=>{})},[]);function logout(){localStorage.removeItem(SESSION_KEY);setSession(null);setCampaign(null)}const money=(value,source="USD")=>new Intl.NumberFormat("pt-BR",{style:"currency",currency}).format(num(value)*(rates[currency]||1)/(rates[source]||1)),common={session,logout,theme,setTheme,currency,setCurrency,dates,setDates,periodKey,setPeriodKey,money};if(!session)return <Login onLogin={setSession}/>;return campaign?<Detail campaign={campaign} common={common} back={()=>setCampaign(null)}/>:<Dashboard common={common} open={setCampaign}/>}
createRoot(document.getElementById("root")).render(<App/>);
